151	            callback(&self.weak_route(), false, |r| {
152	                r.queue.borrow_mut().request_close();
153	                super::ticks::wake();
154	                false
155	            })
156	        }
157	        #[unsafe(method(windowDidBecomeKey:))]
158	        fn focused(&self, _note: &NSNotification) {
159	            callback(&self.weak_route(), (), |r| {
160	                r.focused.set(true);
161	                r.emit(WindowEvent::Focus(true), true)
162	            });
163	        }
164	        #[unsafe(method(windowDidResignKey:))]
165	        fn blurred(&self, _note: &NSNotification) {
166	            callback(&self.weak_route(), (), |r| {
