186	    fn weak_route(&self) -> Weak<RouteState> {
187	        // Fence callback setup too; a corrupt route borrow cannot unwind from an IMP.
188	        crate::guard_native_call(|| self.ivars().route.borrow().clone())
189	            .unwrap_or_else(|_| std::process::abort())
190	    }
191	    pub(crate) fn clear_route(&self) {
192	        *self.ivars().route.borrow_mut() = Weak::new();
193	    }
194	    pub(crate) fn new(mt: MainThread, route: &Rc<RouteState>) -> Retained<Self> {
195	        let this = Self::alloc(mt.marker()).set_ivars(RouteIvars {
196	            route: RefCell::new(Rc::downgrade(route)),
197	        });
