201	pub(crate) fn size(route: &RouteState, backing: bool) {
202	    let Some((window, view)) = route.native() else {
203	        return;
204	    };
205	    let b = view.bounds();
206	    let points = Size {
207	        width: b.size.width,
208	        height: b.size.height,
209	    };
210	    let Some(scale) = super::geometry::scale(&window) else {
211	        route.fail(QueueFaultReason::InputOverflow);
212	        return;
213	    };
214	    let Some(pixels) = super::geometry::pixels(points, scale) else {
215	        route.fail(QueueFaultReason::InputOverflow);
216	        return;
217	    };
218	    route.emit(
219	        if backing {
220	            WindowEvent::BackingScaleChanged { scale, pixels }
221	        } else {
222	            WindowEvent::Resize { points, pixels }
223	        },
224	        false,
225	    );
226	}
