  1	//! Main-thread callback state. Native delegates retain only Weak<RouteState>.
  2	use std::cell::{Cell, RefCell};
  3	use std::rc::{Rc, Weak};
  4	
  5	use super::{queue::EventQueue, types::*};
  6	use crate::{NativeFault, guard_native_call};
  7	use objc2::rc::{Retained, Weak as NativeWeak};
  8	use objc2_app_kit::{NSView, NSWindow};
  9	
 10	pub(crate) struct RouteState {
 11	    pub id: WindowId,
 12	    pub active: Cell<bool>,
 13	    pub focused: Cell<bool>,
 14	    pub queue: RefCell<EventQueue>,
 15	    pub text: RefCell<Option<TextInputState>>,
 16	    pub no_target: Cell<bool>,
 17	    pub composition: RefCell<Option<Composition>>,
 18	    pub native_fault: Cell<Option<NativeFault>>,
 19	    native: RefCell<Option<(NativeWeak<NSWindow>, NativeWeak<NSView>)>>,
 20	    pub tick_generation: Cell<u64>,
 21	    last_timestamp: Cell<f64>,
 22	}
 23	impl RouteState {
 24	    pub fn new(id: WindowId) -> Rc<Self> {
 25	        Rc::new(Self {
 26	            id,
 27	            active: Cell::new(true),
 28	            focused: Cell::new(false),
 29	            queue: RefCell::new(EventQueue::default()),
 30	            text: RefCell::new(None),
 31	            no_target: Cell::new(false),
 32	            composition: RefCell::new(None),
 33	            native_fault: Cell::new(None),
 34	            native: RefCell::new(None),
 35	            tick_generation: Cell::new(0),
 36	            last_timestamp: Cell::new(0.0),
 37	        })
 38	    }
 39	    pub fn bind(&self, window: &Retained<NSWindow>, view: &Retained<NSView>) {
 40	        let weak = (
 41	            NativeWeak::from_retained(window),
 42	            NativeWeak::from_retained(view),
 43	        );
 44	        *self.native.borrow_mut() = Some(weak);
 45	    }
 46	    pub fn native(&self) -> Option<(Retained<NSWindow>, Retained<NSView>)> {
 47	        if !self.active.get() {
 48	            return None;
 49	        }
 50	        // objc2's weak load/clone performs runtime retain bookkeeping, not a
 51	        // message send. Retain/release exceptions are outside our unwind fence.
 52	        let pair = self
 53	            .native
 54	            .borrow()
 55	            .as_ref()
 56	            .map(|(w, v)| (w.clone(), v.clone()))?;
 57	        Some((pair.0.load()?, pair.1.load()?))
 58	    }
 59	    pub fn timestamp(&self, value: f64) -> Option<f64> {
 60	        if !value.is_finite() || value < 0.0 || value > 1.0e12 {
 61	            self.fail(QueueFaultReason::InputOverflow);
 62	            return None;
 63	        }
 64	        let value = value.max(self.last_timestamp.get());
 65	        self.last_timestamp.set(value);
 66	        Some(value)
 67	    }
 68	
 69	    pub fn emit(&self, event: WindowEvent, control: bool) {
 70	        if !self.active.get() {
 71	            return;
 72	        }
 73	        // Enqueue failure is represented by fault/reset latches, or by a reset
 74	        // already disabling ingress. The callback never discards an unreported loss.
 75	        let accepted = self.queue.borrow_mut().push(event, control);
 76	        if !accepted && self.queue.borrow().disabled() {
 77	            self.text.borrow_mut().take();
 78	            self.composition.borrow_mut().take();
 79	            self.no_target.set(false);
 80	            self.queue.borrow_mut().set_external_payload(0);
 81	        }
 82	        super::ticks::wake();
 83	    }
 84	    pub fn fault(&self, reason: QueueFaultReason) {
 85	        if self.active.get() {
 86	            self.queue.borrow_mut().fault(reason);
 87	            super::ticks::wake();
 88	        }
 89	    }
 90	    pub fn fail(&self, reason: QueueFaultReason) {
 91	        if self.active.get() {
 92	            self.queue.borrow_mut().fail(reason);
 93	            self.text.borrow_mut().take();
 94	            self.composition.borrow_mut().take();
 95	            self.no_target.set(false);
 96	            self.queue.borrow_mut().set_external_payload(0);
 97	            super::ticks::wake();
 98	        }
 99	    }
100	    pub fn publish(&self, state: TextInputState, composition: Option<Composition>) -> bool {
101	        let bytes = state.text.len()
102	            + state.marked_attributes.len() * std::mem::size_of::<TextAttributeSpan>()
103	            + composition.as_ref().map_or(0, |c| {
104	                c.text.len() + c.attributes.len() * std::mem::size_of::<TextAttributeSpan>()
105	            });
106	        if !self.queue.borrow_mut().set_external_payload(bytes) {
107	            return false;
108	        }
109	        *self.text.borrow_mut() = Some(state);
110	        *self.composition.borrow_mut() = composition;
111	        self.no_target.set(false);
112	        true
113	    }
114	    pub fn snapshot(&self) -> Option<TextInputState> {
115	        if !self.active.get() || !self.focused.get() {
116	            return None;
117	        }
118	        let snapshot = self.text.borrow().clone();
119	        if snapshot.as_ref().is_none_or(|s| s.source_window != self.id) {
120	            if !self.no_target.get() {
121	                self.fault(QueueFaultReason::TextInputStateMissing);
122	            }
123	            None
124	        } else {
125	            snapshot
126	        }
127	    }
128	    pub fn invalidate(&self) {
129	        self.active.set(false);
130	        self.tick_generation
131	            .set(self.tick_generation.get().saturating_add(1));
132	        self.focused.set(false);
133	        self.text.borrow_mut().take();
134	        self.composition.borrow_mut().take();
135	        self.queue.borrow_mut().clear();
136	        self.native.borrow_mut().take();
137	    }
138	    pub fn callback<T>(&self, fallback: T, f: impl FnOnce() -> T) -> T {
139	        if !self.active.get() {
140	            return fallback;
141	        }
142	        match guard_native_call(f) {
143	            Ok(value) => value,
144	            Err(fault) => {
145	                self.native_fault.set(Some(fault));
146	                self.fail(QueueFaultReason::NativeCallbackFailure);
147	                fallback
148	            }
149	        }
150	    }
151	}
152	pub(crate) fn callback<T>(
153	    weak: &Weak<RouteState>,
154	    fallback: T,
155	    f: impl FnOnce(&Rc<RouteState>) -> T,
156	) -> T {
157	    // The outer fence also covers route upgrades and callback setup. No Rust
158	    // unwind may leave an Objective-C IMP, including failure reporting itself.
159	    match guard_native_call(|| {
160	        if let Some(route) = weak.upgrade() {
161	            route.callback(fallback, || f(&route))
162	        } else {
163	            fallback
164	        }
165	    }) {
166	        Ok(value) => value,
167	        Err(_) => std::process::abort(),
168	    }
169	}
  1	use super::types::{EventBatch, PointerKind, QueueFault, QueueFaultReason, WindowEvent};
  2	use std::collections::VecDeque;
  3	
  4	const CAP: usize = 256;
  5	const ORDINARY: usize = 240;
  6	const PAYLOAD_CAP: usize = 1024 * 1024;
  7	#[derive(Default)]
  8	pub(crate) struct EventQueue {
  9	    entries: VecDeque<(u64, WindowEvent, usize)>,
 10	    sequence: u64,
 11	    payload: usize,
 12	    external_payload: usize,
 13	    dropped: u64,
 14	    disabled: bool,
 15	    retired: bool,
 16	    close_requested: bool,
 17	    fault: Option<(u64, QueueFault)>,
 18	    reset: Option<u64>,
 19	    close: Option<u64>,
 20	    delivered_reset: Option<u64>,
 21	}
 22	impl EventQueue {
 23	    fn next(&mut self) -> u64 {
 24	        // Exhaustion cannot wrap or reopen ingress. Sticky metadata remains bounded.
 25	        self.sequence = self.sequence.checked_add(1).unwrap_or_else(|| {
 26	            self.disabled = true;
 27	            u64::MAX
 28	        });
 29	        self.sequence
 30	    }
 31	    fn sequence_exhausted(&mut self) -> bool {
 32	        if self.retired {
 33	            return true;
 34	        }
 35	        if self.sequence < u64::MAX - 8 {
 36	            return false;
 37	        }
 38	        // Reserve strictly ordered terminal metadata; never wrap or reopen this queue.
 39	        self.retired = true;
 40	        self.disabled = true;
 41	        self.fault = Some((
 42	            u64::MAX - 3,
 43	            QueueFault {
 44	                reason: QueueFaultReason::InputOverflow,
 45	                coalesced_or_dropped: self.dropped,
 46	            },
 47	        ));
 48	        self.reset = Some(u64::MAX - 2);
 49	        if self.close.is_some() {
 50	            self.close = Some(u64::MAX - 1);
 51	        }
 52	        true
 53	    }
 54	    pub(crate) fn fault(&mut self, reason: QueueFaultReason) {
 55	        if self.sequence_exhausted() {
 56	            return;
 57	        }
 58	        if let Some((_, f)) = &mut self.fault {
 59	            f.coalesced_or_dropped = self.dropped;
 60	        } else {
 61	            let s = self.next();
 62	            self.fault = Some((
 63	                s,
 64	                QueueFault {
 65	                    reason,
 66	                    coalesced_or_dropped: self.dropped,
 67	                },
 68	            ));
 69	        }
 70	    }
 71	    pub(crate) fn fail(&mut self, reason: QueueFaultReason) {
 72	        if self.sequence_exhausted() {
 73	            return;
 74	        }
 75	        if self.reset.is_some() || self.delivered_reset.is_some() {
 76	            self.fault(reason);
 77	            return;
 78	        }
 79	        self.disabled = true;
 80	        let s = self.next();
 81	        self.fault = Some((
 82	            s,
 83	            QueueFault {
 84	                reason,
 85	                coalesced_or_dropped: self.dropped,
 86	            },
 87	        ));
 88	        self.reset = Some(self.next());
 89	        if self.close.is_some() {
 90	            self.close = Some(self.next());
 91	        }
 92	    }
 93	    pub(crate) fn push(&mut self, event: WindowEvent, control: bool) -> bool {
 94	        if matches!(event, WindowEvent::CloseRequested) {
 95	            self.request_close();
 96	            return true;
 97	        }
 98	        if self.sequence_exhausted() {
 99	            return false;
100	        }
101	        if self.disabled && !control {
102	            return false;
103	        } // covered by the sequenced reset
104	        let bytes = payload(&event);
105	        if bytes > 64 * 1024 {
106	            self.fail(QueueFaultReason::InputOverflow);
107	            return false;
108	        }
109	        let replace = self
110	            .entries
111	            .back()
112	            .is_some_and(|(_, tail, _)| coalesces(tail, &event));
113	        if replace {
114	            let old = self.entries.back().unwrap().2;
115	            if self.payload - old + bytes + self.external_payload > PAYLOAD_CAP {
116	                self.fail(QueueFaultReason::InputOverflow);
117	                return false;
118	            }
119	            let seq = self.next();
120	            self.payload = self.payload - old + bytes;
121	            *self.entries.back_mut().unwrap() = (seq, event, bytes);
122	            return true;
123	        }
124	        let ordinary = self
125	            .entries
126	            .iter()
127	            .filter(|(_, e, _)| !is_control(e))
128	            .count();
129	        if !control && ordinary >= ORDINARY && lossy(&event) {
130	            self.dropped = self.dropped.saturating_add(1);
131	            self.fault(QueueFaultReason::InputOverflow);
132	            return false;
133	        }
134	        // Non-droppable transitions may consume the sixteen reserved records.
135	        if self.entries.len() == CAP
136	            || self
137	                .payload
138	                .checked_add(bytes)
139	                .and_then(|n| n.checked_add(self.external_payload))
140	                .is_none_or(|n| n > PAYLOAD_CAP)
141	        {
142	            self.fail(QueueFaultReason::InputOverflow);
143	            return false;
144	        }
145	        if self.entries.try_reserve(1).is_err() {
146	            self.fail(QueueFaultReason::AllocationFailure);
147	            return false;
148	        }
149	        let seq = self.next();
150	        self.payload += bytes;
151	        self.entries.push_back((seq, event, bytes));
152	        true
153	    }
154	    pub(crate) fn request_close(&mut self) {
155	        if !self.close_requested {
156	            self.close_requested = true;
157	            self.close = Some(if self.sequence_exhausted() {
158	                u64::MAX - 1
159	            } else {
160	                self.next()
161	            });
162	        }
163	    }
164	    pub(crate) fn acknowledge_reset(&mut self, sequence: u64) -> bool {
165	        if !self.retired && self.delivered_reset == Some(sequence) {
166	            self.delivered_reset = None;
167	            self.disabled = false;
168	            true
169	        } else {
170	            false
171	        }
172	    }
173	    pub(crate) fn set_external_payload(&mut self, bytes: usize) -> bool {
174	        if self
175	            .payload
176	            .checked_add(bytes)
177	            .is_none_or(|n| n > PAYLOAD_CAP)
178	        {
179	            return false;
180	        }
181	        self.external_payload = bytes;
182	        true
183	    }
184	    pub(crate) fn disabled(&self) -> bool {
185	        self.disabled
186	    }
187	    pub(crate) fn has_pending(&self) -> bool {
188	        !self.entries.is_empty()
189	            || self.fault.is_some()
190	            || self.reset.is_some()
191	            || self.close.is_some()
192	    }
193	    pub(crate) fn drain(&mut self, max: usize, native_pending: bool) -> EventBatch {
194	        let mut events = Vec::new();
195	        if events.try_reserve(max.min(CAP + 3)).is_err() {
196	            self.fail(QueueFaultReason::AllocationFailure);
197	            return EventBatch {
198	                events,
199	                pending: true,
200	            };
201	        }
202	        while events.len() < max {
203	            let entry = self.entries.front().map(|v| v.0);
204	            let sticky = [self.fault.as_ref().map(|v| v.0), self.reset, self.close]
205	                .into_iter()
206	                .flatten()
207	                .min();
208	            if entry.is_some() && sticky.is_none_or(|s| entry.unwrap() < s) {
209	                let (_, event, bytes) = self.entries.pop_front().unwrap();
210	                self.payload -= bytes;
211	                events.push(event);
212	                continue;
213	            }
214	            let Some(seq) = sticky else {
215	                break;
216	            };
217	            if self.fault.as_ref().is_some_and(|v| v.0 == seq) {
218	                events.push(WindowEvent::QueueFault(self.fault.take().unwrap().1));
219	            } else if self.reset == Some(seq) {
220	                self.reset = None;
221	                self.delivered_reset = Some(seq);
222	                events.push(WindowEvent::InputReset {
223	                    sequence: seq,
224	                    all_keys_up: true,
225	                    all_buttons_up: true,
226	                });
227	            } else {
228	                self.close = None;
229	                if !self.retired {
230	                    self.close_requested = false;
231	                }
232	                events.push(WindowEvent::CloseRequested);
233	            }
234	        }
235	        EventBatch {
236	            events,
237	            pending: self.has_pending() || native_pending,
238	        }
239	    }
240	    pub(crate) fn clear(&mut self) {
241	        self.entries.clear();
242	        self.payload = 0;
243	        self.external_payload = 0;
244	        self.fault = None;
245	        self.reset = None;
246	        self.close = None;
247	        self.disabled = true;
248	    }
249	    pub(crate) const fn native_budget() -> usize {
250	        64
251	    }
252	}
253	fn payload(e: &WindowEvent) -> usize {
254	    match e {
255	        WindowEvent::TextCommitted(s) | WindowEvent::TextCommand(s) => s.len(),
256	        WindowEvent::TextCommittedWithReplacement { text, .. } => text.len(),
257	        WindowEvent::Composition(c) => {
258	            c.text.len()
259	                + c.attributes.len() * std::mem::size_of::<super::types::TextAttributeSpan>()
260	        }
261	        _ => 0,
262	    }
263	}
264	fn lossy(e: &WindowEvent) -> bool {
265	    matches!(e,WindowEvent::Pointer(p) if p.kind==PointerKind::Move)
266	        || matches!(
267	            e,
268	            WindowEvent::Resize { .. } | WindowEvent::BackingScaleChanged { .. }
269	        )
270	}
271	fn coalesces(a: &WindowEvent, b: &WindowEvent) -> bool {
272	    matches!((a,b),(WindowEvent::Pointer(a),WindowEvent::Pointer(b)) if a.kind==PointerKind::Move && b.kind==PointerKind::Move)
273	        || matches!(
274	            (a, b),
275	            (WindowEvent::Resize { .. }, WindowEvent::Resize { .. })
276	                | (
277	                    WindowEvent::BackingScaleChanged { .. },
278	                    WindowEvent::BackingScaleChanged { .. }
279	                )
280	        )
281	}
282	fn is_control(e: &WindowEvent) -> bool {
283	    matches!(
284	        e,
285	        WindowEvent::Open
286	            | WindowEvent::Focus(_)
287	            | WindowEvent::AppearanceChanged { .. }
288	            | WindowEvent::CloseRequested
289	            | WindowEvent::QueueFault(_)
290	            | WindowEvent::InputReset { .. }
291	    )
292	}
