297	    #[test]
298	    fn terminal_sequence_metadata_cannot_wrap_or_reopen_ingress() {
299	        let mut q = EventQueue::default();
300	        q.sequence = u64::MAX - 8;
301	        assert!(!q.push(WindowEvent::Focus(true), true));
302	        q.request_close();
303	        let events = q.drain(4, false).events;
304	        assert!(matches!(events[0], WindowEvent::QueueFault(_)));
305	        assert!(matches!(events[1],WindowEvent::InputReset{sequence,..} if sequence==u64::MAX-2));
306	        assert!(matches!(events[2], WindowEvent::CloseRequested));
307	        assert!(!q.acknowledge_reset(u64::MAX - 2));
308	        assert!(!q.push(WindowEvent::Focus(true), true));
309	    }
