   162	    pub fn request_ticks(&mut self, enabled: bool) -> Result<(), WindowError> {
   163	        let h = self.handles()?;
   164	        let owner = self.owner.upgrade().ok_or(WindowError::ExpiredOwner)?;
   165	        let previous = {
   166	            let mut state = owner.borrow_mut();
   167	            let r = slot_mut(&mut state, self.id)?.record.as_mut().unwrap();
   168	            if enabled
   169	                && r.timer
   170	                    .as_ref()
   171	                    .is_some_and(|t| t.1 == h.route.tick_generation.get())
   172	            {
   173	                return Ok(());
   174	            }
   175	            r.timer.take()
   176	        };
   177	        let generation = h.route.tick_generation.get().checked_add(1).unwrap_or(0);
   178	        h.route.tick_generation.set(generation);
   179	        if let Some(timer) = previous {
   180	            if let Err(fault) = super::ticks::cancel(&timer.0) {
   181	                let mut state = owner.borrow_mut();
   182	                if let Ok(slot) = slot_mut(&mut state, self.id) {
   183	                    slot.record.as_mut().unwrap().timer = Some(timer);
   184	                }
   185	                return Err(WindowError::Native(fault));
   186	            }
   187	        }
   188	        if !enabled {
   189	            return Ok(());
   190	        }
   191	        if generation == 0 {
   192	            return Err(WindowError::QueueFault);
   193	        }
   194	        let timer = match guard_native_call(|| {
   195	            let target = super::callbacks::TickTarget::new(h.mt, &h.route, generation);
   196	            super::ticks::install(&target)
   197	        })
   198	        .and_then(|r| r)
   199	        {
   200	            Ok(timer) => timer,
   201	            Err(fault) => {
   202	                h.route
   203	                    .tick_generation
   204	                    .set(generation.checked_add(1).unwrap_or(0));
   205	                return Err(WindowError::Native(fault));
   206	            }
   207	        };
   208	        // A timer installation may reenter; validate owner and generation again.
   209	        let mut state = owner.borrow_mut();
   210	        match slot_mut(&mut state, self.id) {
   211	            Ok(slot) => slot.record.as_mut().unwrap().timer = Some((timer, generation)),
   212	            Err(error) => {
   213	                drop(state);
   214	                let _ = super::ticks::cancel(&timer);
   215	                return Err(error);
   216	            }
   217	        }
   218	        drop(state);
   219	        super::ticks::wake();
   220	        Ok(())
   221	    }
