    58	    if count > 64 * 1024 {
    59	        route.fault(QueueFaultReason::InputOverflow);
    60	        return None;
    61	    }
    62	    let mut units = Vec::new();
    63	    if units.try_reserve_exact(count).is_err() {
    64	        route.fail(QueueFaultReason::AllocationFailure);
    65	        return None;
    66	    }
    67	    units.resize(count, 0u16);
