    82	            route.fault(QueueFaultReason::InputOverflow);
    83	            return None;
    84	        }
    85	        if text.try_reserve(ch.len_utf8()).is_err() {
    86	            route.fail(QueueFaultReason::AllocationFailure);
    87	            return None;
    88	        }
    89	        text.push(ch);
    90	    }
