   119	                }
   120	                if spans.try_reserve(1).is_err() {
   121	                    route.fail(QueueFaultReason::AllocationFailure);
   122	                    return None;
   123	                }
   124	                spans.push(TextAttributeSpan {
   125	                    range_utf8: requested(&text, effective)?,
   126	                    kind,
   127	                    value,
   128	                });
   129	            }
   130	            index = end;
   131	        }
   132	    }
   133	    if text.len() + spans.len() * std::mem::size_of::<TextAttributeSpan>() > 64 * 1024 {
