use crate::{NativeFault, guard_native_call};
pub(crate) fn next_generation(generation: u32) -> Option<u32> {
    generation.checked_add(1).filter(|v| *v != 0)
}
pub(crate) fn destroy(mut record: WindowRecord) -> Result<(), NativeFault> {
    record.route.invalidate();
    record.view.clear_route();
    record._delegate.clear_route();
    let mut fault = None;
    if let Some(timer) = record.timer.take() {
        if let Err(f) = super::ticks::cancel(&timer.0) {
            fault = Some(f);
        }
    }
    // Cleanup continues after individual faults. All routes were invalidated
    // before any reentrant call, and no app/route RefCell borrow is held here.
    for result in [
        guard_native_call(|| record.native.setDelegate(None)),
        guard_native_call(|| {
            let _ = record.native.makeFirstResponder(None);
        }),
        guard_native_call(|| record.native.setContentView(None)),
        guard_native_call(|| record.native.close()),
    ] {
        if let Err(f) = result {
            fault.get_or_insert(f);
        }
    }
    // Retained/weak release and native dealloc are outside objc2 catch-all and may
    // terminate if foreign cleanup throws. No universal exception fence is claimed.
    drop(record);
    super::ticks::wake();
    fault.map_or(Ok(()), Err)
}
use super::callbacks::TickTarget;
use crate::{NativeFault, guard_native_call};
use objc2::rc::Retained;
use objc2::{runtime::AnyObject, sel};
use objc2_core_foundation::CFRunLoop;
use objc2_foundation::{NSRunLoop, NSRunLoopCommonModes, NSTimer};

pub(crate) fn wake() {
    // CF is outside catch-all. Apple's process-lifetime main run loop is valid;
    // wake_up neither throws an ObjC exception nor synchronously runs callbacks.
    if let Some(main) = CFRunLoop::main() {
        main.wake_up();
    }
}
pub(crate) fn install(target: &TickTarget) -> Result<Retained<NSTimer>, NativeFault> {
    let timer = guard_native_call(|| unsafe {
        // SAFETY: target implements tick:(NSTimer*) with exact void ABI; timer
        // retains it and is scheduled exclusively on the process main run loop.
        let object: &AnyObject = target.as_ref();
        NSTimer::timerWithTimeInterval_target_selector_userInfo_repeats(
            1.0 / 60.0,
            object,
            sel!(tick:),
            None,
            true,
        )
    })?;
    let result = guard_native_call(|| unsafe {
        NSRunLoop::mainRunLoop().addTimer_forMode(&timer, NSRunLoopCommonModes)
    });
    if let Err(fault) = result {
        let _ = guard_native_call(|| timer.invalidate());
        return Err(fault);
    }
    wake();
    Ok(timer)
}
pub(crate) fn cancel(timer: &NSTimer) -> Result<(), NativeFault> {
    guard_native_call(|| timer.invalidate())
}

